for s in range(1,4):
 for n in range(3,20):
  v=[[z3.Int(f'x{i}_{j}') for j in range(n)] for i in range(s)]
  sol=z3.Solver()
  for row in v:
   sol.add(z3.Distinct(row));sol.add(*[z3.And(x>=0,x<n) for x in row])
  for a in range(n):
   for b in range(a+1,n):
